// List-directed input
// ---------------------------------------------------------------------------

bool is_sep(char c) { return c == ' ' || c == ',' || c == '\t'; }

// One list-directed REAL datum out of `rec` starting at `pos`.
// Returns false on a malformed datum (the reference's IOS > 0).
bool scan_real(const std::string& rec, size_t& pos, double& value) {
    const size_t n = rec.size();
    size_t i = pos;
    const size_t start = i;
    if (i < n && (rec[i] == '+' || rec[i] == '-')) ++i;
    size_t digits = 0;
    while (i < n && rec[i] >= '0' && rec[i] <= '9') { ++i; ++digits; }
    if (i < n && rec[i] == '.') {
        ++i;
        while (i < n && rec[i] >= '0' && rec[i] <= '9') { ++i; ++digits; }
    }
    if (digits == 0) return false;
    // Exponent: an explicit letter, or gfortran's letter-less signed form.
    if (i < n && (rec[i] == 'e' || rec[i] == 'E' || rec[i] == 'd' || rec[i] == 'D' ||
                  rec[i] == 'q' || rec[i] == 'Q')) {
        size_t save = i;
        ++i;
        if (i < n && (rec[i] == '+' || rec[i] == '-')) ++i;
        size_t ed = 0;
        while (i < n && rec[i] >= '0' && rec[i] <= '9') { ++i; ++ed; }
        if (ed == 0) { i = save; }
    } else if (i < n && (rec[i] == '+' || rec[i] == '-')) {
        size_t save = i;
        ++i;
        size_t ed = 0;
        while (i < n && rec[i] >= '0' && rec[i] <= '9') { ++i; ++ed; }
        if (ed == 0) { i = save; }
    }
    // The datum must end at a separator or at the end of the record.
    if (i < n && !is_sep(rec[i]) && rec[i] != '/') return false;

    // strtod does not know 'D'/'Q'; normalise the exponent letter, and supply
    // an 'e' for the letter-less form so the same converter handles both.
    std::string tok = rec.substr(start, i - start);
    for (size_t k = 1; k < tok.size(); ++k) {
        if (tok[k] == 'd' || tok[k] == 'D' || tok[k] == 'q' || tok[k] == 'Q') tok[k] = 'e';
        else if ((tok[k] == '+' || tok[k] == '-') && tok[k - 1] != 'e' && tok[k - 1] != 'E')
            { tok.insert(k, 1, 'e'); ++k; }
    }
    const char* c = tok.c_str();
    char* end = nullptr;
    value = std::strtod(c, &end);
    if (end == c) return false;
    pos = i;
    return true;
}

// An unsigned integer repeat count followed by '*'. Returns 0 when there is none.
long scan_repeat(const std::string& rec, size_t& pos) {
    size_t i = pos;
    const size_t n = rec.size();
    size_t d = 0;
    long r = 0;
    while (i < n && rec[i] >= '0' && rec[i] <= '9') { r = r * 10 + (rec[i] - '0'); ++i; ++d; }
    if (d == 0 || i >= n || rec[i] != '*' || r <= 0) return 0;
    pos = i + 1;
    return r;
}

// The IOSTAT contract of the reference's reads, reproduced:
//   0   the whole list was satisfied (or `/` ended it)
//  <0   the input ran out first (end of file / end of an internal record)
//  >0   a datum was malformed
enum class ListIO { Ok = 0, Eof = -1, Bad = 1 };

// `records` is a cursor over a source of records: an external file reads on,
// an internal file has exactly one.
struct RecordSource {
    virtual ~RecordSource() = default;
    virtual bool next(std::string& rec) = 0;
};

struct FileRecords : RecordSource {
    std::FILE* fp;
    explicit FileRecords(std::FILE* f) : fp(f) {}
    bool next(std::string& rec) override {
        if (fp == nullptr) return false;
        rec.clear();
        int c;
        bool any = false;
        while ((c = std::fgetc(fp)) != EOF) {
            any = true;
            if (c == '\n') return true;
            if (c != '\r') rec.push_back(static_cast<char>(c));
        }
        return any;   // a final record with no newline is still a record
    }
};

struct OneRecord : RecordSource {
    std::string rec;
    bool done = false;
    explicit OneRecord(std::string r) : rec(std::move(r)) {}
    bool next(std::string& out) override {
        if (done) return false;
        done = true;
        out = rec;
        return true;
    }
};

ListIO read_list_reals(RecordSource& src, double* data, int count) {
    if (count <= 0) {
        // An EMPTY io-list still performs record positioning for an advancing
        // transfer, so it consumes one record and reports end-of-file when
        // there is none. Returning Ok unconditionally instead would make the
        // reference's `DO WHILE (IOS == 0)` loop non-terminating.
        std::string skip;
        return src.next(skip) ? ListIO::Ok : ListIO::Eof;
    }
    std::string rec;
    size_t pos = 0;
    bool have = false;
    int filled = 0;
    long repeat = 0;
    bool repeat_null = false;
    double repeat_value = 0.0;

    while (filled < count) {
        if (repeat > 0) {
            if (!repeat_null) data[filled] = repeat_value;
            ++filled;
            --repeat;
            continue;
        }
        if (!have) {
            if (!src.next(rec)) return ListIO::Eof;
            pos = 0;
            have = true;
        }
        // gfortran treats a TAB in list-directed input as a blank, not as the
        // comma that separates a null value. Only a comma makes a null.
        while (pos < rec.size() && (rec[pos] == ' ' || rec[pos] == '\t')) ++pos;
        if (pos >= rec.size()) { have = false; continue; }
        if (rec[pos] == '/') return ListIO::Ok;          // terminator
        if (rec[pos] == ',') {                           // a null value
            ++pos;
            ++filled;                                     // item left unchanged
            continue;
        }
        long r = scan_repeat(rec, pos);
        if (r > 0) {
            if (pos >= rec.size() || is_sep(rec[pos]) || rec[pos] == '/') {
                repeat = r; repeat_null = true;           // `r*` -- r null values
                continue;
            }
            double v;
            if (!scan_real(rec, pos, v)) return ListIO::Bad;
            repeat = r; repeat_null = false; repeat_value = v;
            continue;
        }
        double v;
        if (!scan_real(rec, pos, v)) return ListIO::Bad;
        data[filled] = v;
        ++filled;
        // Consume the separator that ended the datum. A comma is the separator
        // itself; blanks are skipped by the loop head next time round.
        if (pos < rec.size() && rec[pos] == ',') ++pos;
    }
    return ListIO::Ok;
}

