void Read_OL_Input(char* OL_InputFileName, int Unit_OL_Input, int NumChannels, double** Channels,
                   int* n_Channels_rows, int* n_Channels_cols, errorvariables_view_t* ErrVar) {
    (void)Unit_OL_Input;   // a Fortran unit number has no C representation; the
                           // reference opens and closes it itself, so the unit
                           // is not part of the (data in) -> (data out) contract.

    // INTENT(OUT) ALLOCATABLE: not allocated until the reference allocates it.
    // C_NULL_PTR is what the wrapper reads as "not allocated" (P6).
    *Channels = nullptr;
    *n_Channels_rows = 0;
    *n_Channels_cols = 0;

    const std::string name = fortran_trim(OL_InputFileName, OL_INPUT_FILENAME_LEN);

    // INQUIRE (FILE = OL_InputFileName, EXIST = FileExists)
    struct stat sb;
    const bool FileExists = !name.empty() && ::stat(name.c_str(), &sb) == 0;

    if (!FileExists) {
        ErrVar->aviFAIL = -1;
        assign_errmsg(ErrVar, name + " does not exist");
    } else {
        // OPEN(..., STATUS='OLD', FORM='FORMATTED', IOSTAT=IOS, ACTION='READ')
        std::FILE* fp = std::fopen(name.c_str(), "r");
        if (fp == nullptr) {
            ErrVar->aviFAIL = -1;
            assign_errmsg(ErrVar, "Cannot open " + name);
        } else {
            FileRecords src(fp);
            std::vector<double> TmpData(NumChannels > 0 ? static_cast<size_t>(NumChannels) : 0, 0.0);

            // LINE = '!' ; NumComments = -1
            std::string Line = "!";
            int NumComments = -1;
            ListIO ios = ListIO::Ok;

            while (Line.find('!') != std::string::npos ||
                   Line.find('#') != std::string::npos ||
                   Line.find('%') != std::string::npos) {
                ++NumComments;
                std::string rec;
                if (src.next(rec)) {
                    // CHARACTER(1024) :: Line -- an 'A' edit read blank-fills
                    // the whole declared width and TRUNCATES a longer record.
                    if (rec.size() > 1024) rec.resize(1024);
                    Line = rec;
                } else {
                    // The record source ran out. gfortran leaves LINE unchanged
                    // on an end-of-file read, which would spin here forever on
                    // an all-comment file; the reference has the same hole and
                    // this transcription does not invent an answer for it --
                    // it stops, which is the only behaviour that terminates.
                    break;
                }
            }

            int NumDataLines = 0;

            // READ(LINE,*,IOSTAT=IOS) ( TmpData(I), I=1,NumChannels )
            {
                OneRecord one(Line);
                ios = read_list_reals(one, TmpData.data(), NumChannels);
            }

            while (ios == ListIO::Ok) {
                ++NumDataLines;
                ios = read_list_reals(src, TmpData.data(), NumChannels);
            }

            if (NumDataLines < 1) {
                // WRITE (NumString,'(I11)') NumComments -- an I11 edit is RIGHT
                // JUSTIFIED in eleven columns, and CHARACTER(15) blank-pads the
                // remaining four. TRIM removes the four; the LEADING blanks of
                // the I11 field stay, and they are in the message.
                char NumString[16];
                std::snprintf(NumString, sizeof(NumString), "%11d", NumComments);
                std::string ns(NumString);
                while (!ns.empty() && ns.back() == ' ') ns.pop_back();
                ErrVar->aviFAIL = -1;
                assign_errmsg(ErrVar,
                              "Error: " + ns +
                              " comment lines were found in the uniform wind file, "
                              "but the first data line does not contain the proper format.");
                std::fclose(fp);
                fp = nullptr;
            }

            // ALLOCATE(Channels(NumDataLines,NumChannels))
            const long rows = NumDataLines;
            const long cols = NumChannels;
            const long nelem = (rows > 0 && cols > 0) ? rows * cols : 0;
            double* buf = static_cast<double*>(std::malloc(
                static_cast<size_t>(nelem > 0 ? nelem : 1) * sizeof(double)));
            *Channels = buf;
            *n_Channels_rows = static_cast<int>(rows);
            *n_Channels_cols = static_cast<int>(cols);

            if (fp != nullptr) {
                // REWIND, then skip the comment lines
                std::rewind(fp);
                for (int i = 1; i <= NumComments; ++i) {
                    std::string rec;
                    if (!src.next(rec)) break;
                }

                for (long i = 1; i <= rows; ++i) {
                    ListIO r = read_list_reals(src, TmpData.data(), NumChannels);
                    if (r == ListIO::Bad) {
                        std::fclose(fp);
                        fp = nullptr;
                        src.fp = nullptr;
                    }
                    // Channels(I,:) = TmpData -- Fortran is column-major, so the
                    // row is STRIDED: element (i,j) sits at (j-1)*rows + (i-1).
                    for (long j = 1; j <= cols; ++j)
                        buf[(j - 1) * rows + (i - 1)] = TmpData[static_cast<size_t>(j - 1)];
                }
            }
            if (fp != nullptr) std::fclose(fp);
        }
    }

    if (ErrVar->aviFAIL < 0)
        assign_errmsg(ErrVar, "Read_OL_Input:" + trimmed_errmsg(ErrVar));
}

